#!/bin/bash
# STC 智能风扇控制器 — 一键安装脚本 (v3)
# 用法: 复制本脚本到目标飞牛NAS, 然后执行:  bash stc-fan-install.sh
# 功能: 解压项目文件 → 建虚拟环境 → 加权限组 → 配置开机自启 → 启动服务

set -e

BASE64_DATA=""

echo ""
echo "========================================"
echo "  STC 智能风扇控制器 一键安装 v3"
echo "========================================"
echo ""

# ── 检测环境 ──
if ! command -v python3 &>/dev/null; then
    echo "❌ 未找到 python3, 请先安装 Python 3.10+"
    exit 1
fi
if ! command -v systemctl &>/dev/null; then
    echo "⚠ 未找到 systemd, 将仅解压文件不配置自启"
    NO_SYSTEMD=1
fi

# ── 安装目录 ──
DEFAULT_DIR="/vol1/@appdata/trim.hermes/workspace/fan-controller"
read -p "安装目录 [$DEFAULT_DIR]: " INSTALL_DIR
INSTALL_DIR=${INSTALL_DIR:-$DEFAULT_DIR}

# ── 1. 解压项目文件 ──
echo "[1/4] 解压项目文件..."
mkdir -p "$(dirname "$INSTALL_DIR")"
echo "$BASE64_DATA" | base64 -d | tar xzf - -C "$(dirname "$INSTALL_DIR")"
# 修正目录名(包内是 fan-controller/)
if [ "$(basename "$INSTALL_DIR")" != "fan-controller" ]; then
    mv "$(dirname "$INSTALL_DIR")/fan-controller" "$INSTALL_DIR" 2>/dev/null || true
fi
cd "$INSTALL_DIR"

# ── 2. 虚拟环境 ──
echo "[2/4] 创建 Python 虚拟环境..."
python3 -m venv --system-site-packages venv 2>/dev/null || python3 -m venv venv
./venv/bin/pip install -q pyserial-asyncio 2>/dev/null || true
echo "    依赖: $(./venv/bin/pip list 2>/dev/null | grep -iE 'serial|fastapi|uvicorn' | tr '\n' ' ')"

# ── 3. 用户权限组 ──
RUN_USER=${SUDO_USER:-$(whoami)}
[ "$RUN_USER" = "root" ] && RUN_USER=$(ls -ld "$INSTALL_DIR" | awk '{print $3}')
echo "[3/4] 添加用户到 dialout/disk 组 ($RUN_USER)..."
sudo usermod -aG dialout "$RUN_USER" 2>/dev/null || true
sudo usermod -aG disk "$RUN_USER" 2>/dev/null || true

# ── 4. 开机自启 ──
echo "[4/4] 配置开机自启..."
if [ -z "$NO_SYSTEMD" ]; then
    # systemd 服务
    SERVICE_FILE="/etc/systemd/system/stc-fan.service"
    sudo tee "$SERVICE_FILE" > /dev/null << EOF
[Unit]
Description=STC Smart Fan Controller
After=network.target

[Service]
Type=simple
User=$RUN_USER
WorkingDirectory=$INSTALL_DIR
ExecStart=$INSTALL_DIR/start.sh
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
EOF
    sudo systemctl daemon-reload 2>/dev/null || true
    sudo systemctl enable stc-fan.service 2>/dev/null || true
    sudo systemctl restart stc-fan.service 2>/dev/null || true
    echo "    systemd 服务 stc-fan.service 已配置"
else
    # 无 systemd: crontab @reboot
    chmod +x "$INSTALL_DIR/start.sh"
    ( crontab -l 2>/dev/null | grep -v "fan-controller/start.sh"; \
      echo "@reboot sleep 30 && $INSTALL_DIR/start.sh >> $INSTALL_DIR/auto-start.log 2>&1" ) | crontab -
    echo "    crontab @reboot 已配置"
fi

# ── 启动验证 ──
echo ""
echo "正在启动服务..."
sleep 5
IP=$(hostname -I 2>/dev/null | awk '{print $1}')
if curl -s -m 3 "http://127.0.0.1:8780/api/info" >/dev/null 2>&1; then
    echo "✅ 服务启动成功!"
else
    echo "⚠ 服务可能还在启动中, 稍后访问确认"
fi

echo ""
echo "========================================"
echo "  ✅  安装完成!"
echo "========================================"
echo ""
echo "  Web 控制台:  http://${IP:-<NAS_IP>}:8780"
echo ""
echo "  常用命令:"
echo "    sudo systemctl status stc-fan     # 查看状态"
echo "    sudo systemctl restart stc-fan    # 重启"
echo "    sudo journalctl -u stc-fan -f     # 日志"
echo ""
echo "  ⚠ 提示:"
echo "    1. 组修改需重新登录才生效(当前会话可先忽略, 服务用 sg 提权运行)"
echo "    2. 控制器插在哪个USB口都行, 服务会自动扫描 ttyACM*"
echo "    3. 温控参数在 Web UI 上设置, 自动持久化"
echo ""
